// ROUTE PAGES: informational first, and factually about the WHOLE journey.
//
// Aviv, 2026-08-28: "its informational so for example bangkok to koh phangan is done alot of times
// through an inner flight to surat thani or koh samui. make sure all of the routes are factually
// correct for their explanation."
//
// That is the whole design constraint. A page that describes only the legs we happen to SELL is not
// informational, it is a catalogue with a Hebrew wrapper, and a traveller who reads it and then
// discovers everyone actually flies to Surat Thani will not trust the rest of it either. So each page
// describes how the journey is really made, including the options we do not sell, and is honest about
// which parts we handle.
//
// NO PRICES ANYWHERE, by Aviv's instruction. Durations, modes, stations, piers and departure patterns
// are stable facts; prices are not, and a stale number on a static page would also contradict the bot,
// which is the same failure that cost a day of work inside the product.
//
// Every route below was checked against live 12Go inventory before being written (all 27 candidates
// had real service) and then RESEARCHED for the real-world picture, because inventory tells you what
// is bookable, not what people actually do.
//
//   node build-routes.mjs
import { writeFileSync, mkdirSync, readFileSync, readdirSync, existsSync, rmSync } from "node:fs";
import { createHash } from "node:crypto";

const WA_NUMBER = "972559171333";

// EVERY LINK INTO WHATSAPP ARRIVES WITH THE MESSAGE ALREADY WRITTEN.
//
// Aviv, 2026-08-29: "all the links leading to my whatsapp on the site need to have a prewritten
// message." On a route page that is worth more than a nicety: the customer lands in the chat with
// their own route already typed, which is a whole turn of the bot asking where from and where to
// that never has to happen. The date and the party size are still theirs to give.
//
// Written the way THEY would write it, because it lands in their outbox and they can edit it. A
// paragraph of marketing copy in someone's mouth reads as spam and gets deleted, and the referral
// link learned the same lesson: no emoji, one plain sentence.
const waLink = (text) => `https://wa.me/${WA_NUMBER}?text=${encodeURIComponent(text)}`;

// ...AND IT SAYS WHERE THEY CAME FROM. Aviv, 2026-09-02: "add the source tags to the site links."
// Of the bot's first 36 conversations, 30 arrived untagged, because these links opened with a bare
// "היי! אשמח לבדוק כרטיס" — indistinguishable from word of mouth. Forty-nine route pages, and no way
// to tell whether any of them had ever produced a customer.
//
// "הגעתי מהאתר" is the same arrival shape the partner links already use, and referrals.CHANNELS reads
// it as one of OURS: a first-class row in the report, never a commissionable partner. The route rides
// in the same sentence, so which PAGE sent someone is readable without a tag per page.
//
// Still written the way THEY would write it — it lands in their outbox and they can edit it before
// sending, so it stays one plain sentence with no emoji and no marketing.
const FROM_SITE = "היי! הגעתי מהאתר ואשמח לבדוק כרטיס";
const WA = waLink(FROM_SITE);
const BUILD_DATE = new Date().toISOString().slice(0, 10);

