// WHAT ABOUT FLYING? EVERY PAGE ANSWERS IT, INCLUDING THE PAGES WHERE THE ANSWER IS NO.
//
// Aviv, 2026-08-28: "mumbai to goa is also a direct inner flight, to all the pages all the flights
// aswell, it needs to be very informational and correct or people wont trust us."
//
// The trust argument cuts both ways, and the NO answers are the ones that earn it. Three of these
// routes have an airport that shows up on maps and in old blog posts and cannot actually be flown to:
// Pai (no scheduled service since Kan Air stopped in 2017), Sa Pa (groundbreaking 2022, main works
// still not started in 2026, target now before October 2027) and Mui Ne / Phan Thiet (civil terminal
// broke ground April 2026, roughly a two year build). A traveller who books around a flight that does
// not exist is a traveller we lost, so those pages say so explicitly.
//
// Two more are traps of the same shape as the Thivim / Madgaon station split already on the Mumbai
// page: Goa has TWO airports about 90 minutes apart (Mopa/Manohar GOX in the north, opened January
// 2023, and Dabolim GOI in the south, inside a naval air station), and Siem Reap's airport MOVED in
// late 2023 from 7km outside town to roughly 50km away, which quietly erases much of the flight's
// advantage over the bus.
//
// Researched 2026-08-28. Durations are scheduled block times and are stable; frequencies are
// described in words rather than numbers wherever a number would rot.
//
// NOT SOLD BY THE BOT, ON PURPOSE. Aviv, earlier: "the agent dosent handle them but a human operator
// will take over the chat and handle it." So every flight that is real ends by saying a person takes
// it from there, and that we do the ground legs around it. No page implies the bot will book a seat.
