  "yogyakarta-bromo": {"t":"אין טיסה בקו הזה","no":true,"p":"לברומו אין שדה תעופה. אפשר לטוס לסורבאיה ומשם לנסוע לפרובולינגו, אבל מיוגיאקרטה הרכבת פשוטה יותר."},
  "bromo-ijen": {"t":"אין טיסה בקו הזה","no":true,"p":"אין טיסה בין ברומו לאיג'ן. הדרך היא ברכבת או ברכב לבניוואנגי."},
