const quickAnswer = (r) => QUICK[r.slug] ? QUICK[r.slug].map(([m, t, p]) => `${m}: ${t}, ${p}`).join(". ") + `. המחירים להמחשה בלבד, לפי חיפוש לתאריך ${QUICK_DATE}. למחיר העדכני ביותר כתבו לנו בוואטסאפ.` : "";

